14	/// A newtype to represent an immediate offset argument for a heap access.
15	#[derive(Debug, Copy, Clone)]
16	pub(crate) struct ImmOffset(u32);
17	
18	impl ImmOffset {
19	    /// Construct an [ImmOffset] from a u32.
20	    pub fn from_u32(raw: u32) -> Self {
21	        Self(raw)
22	    }
23	
24	    /// Return the underlying u32 value.
25	    pub fn as_u32(&self) -> u32 {
26	        self.0
27	    }
28	}
