41	/// Aarch64 MacroAssembler.
42	pub(crate) struct MacroAssembler {
43	    /// This value represents the maximum stack size seen while compiling the
44	    /// function. While the function is still being compiled its value will not
45	    /// be valid (the stack will grow and shrink as space is reserved and freed
46	    /// during compilation), but once all instructions have been seen this value
47	    /// will be the maximum stack usage seen.
48	    sp_max: u32,
49	
50	    /// Add-with-immediate patchable instruction sequence used to add the
51	    /// constant stack max to a register.
52	    stack_max_use_add: Option<PatchableAddToReg>,
53	
54	    /// Low level assembler.
55	    asm: Assembler,
56	    /// Stack pointer offset.
57	    sp_offset: u32,
58	    /// The target pointer size.
59	    ptr_size: OperandSize,
60	    /// Scratch register scope.
61	    scratch_scope: RegAlloc,
62	    /// Shared flags.
63	    shared_flags: settings::Flags,
64	}
65	
66	impl MacroAssembler {
67	    /// Create an Aarch64 MacroAssembler.
68	    pub fn new(
69	        ptr_size: impl PtrSize,
70	        shared_flags: settings::Flags,
71	        isa_flags: aarch64::settings::Flags,
72	    ) -> Result<Self> {
73	        Ok(Self {
74	            sp_max: 0,
75	            stack_max_use_add: None,
76	            asm: Assembler::new(shared_flags.clone(), isa_flags),
77	            sp_offset: 0u32,
78	            ptr_size: ptr_type_from_ptr_size(ptr_size.size()).try_into()?,
79	            scratch_scope: RegAlloc::from(scratch_gpr_bitset(), scratch_fpr_bitset()),
80	            shared_flags,
81	        })
82	    }
83	
84	    /// Add the maximum stack used to a register, recording an obligation to update the
85	    /// add-with-immediate instruction emitted to use the real stack max when the masm is being
86	    /// finalized.
87	    fn add_stack_max(&mut self, reg: WritableReg, tmp: WritableReg) {
88	        assert!(self.stack_max_use_add.is_none());
89	        let patch = PatchableAddToReg::new(reg, tmp, self.asm.buffer_mut());
90	        self.stack_max_use_add.replace(patch);
91	    }
92	
93	    /// Ensures that the stack pointer remains 16-byte aligned for the duration
94	    /// of the provided function. This alignment is necessary for AArch64
95	    /// compliance, particularly for signal handlers that may be invoked
96	    /// during execution. While the compiler doesn't directly use the stack
97	    /// pointer for memory addressing, maintaining this alignment is crucial
98	    /// to prevent issues when handling signals.
99	    pub fn with_aligned_sp<F, T>(&mut self, f: F) -> Result<T>
100	    where
101	        F: FnOnce(&mut Self) -> Result<T>,
102	    {
103	        let mut aligned = false;
104	        let alignment: u32 = <Aarch64ABI as ABI>::call_stack_align().into();
105	        let addend: u32 = <Aarch64ABI as ABI>::initial_frame_size().into();
106	        let delta = calculate_frame_adjustment(self.sp_offset()?.as_u32(), addend, alignment);
107	        if delta != 0 {
108	            self.sub(
109	                writable!(regs::sp()),
110	                // Since we don't need to synchronize the shadow stack pointer
111	                // when freeing stack space [^1], the stack pointer may become
112	                // out of sync with the primary shadow stack pointer. Therefore,
113	                // we use the shadow stack pointer as the reference for
114	                // calculating any alignment delta (self.sp_offset).
115	                //
116	                // [1]: This approach avoids an unnecessary move instruction and
117	                // maintains the invariant of not accessing memory below the
118	                // current stack pointer, preventing issues with signal handlers
119	                // and interrupts.
120	                regs::shadow_sp(),
121	                RegImm::i32(delta as i32),
122	                OperandSize::S64,
123	            )?;
124	
125	            aligned = true;
126	        }
127	
128	        let res = f(self)?;
129	
130	        if aligned {
131	            self.move_shadow_sp_to_sp();
132	        }
133	
134	        Ok(res)
135	    }
136	}
